draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // wisdom
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  // lesson
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('LESSON', W/2, H/2-100);

  // life
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();

  // applying
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('APPLYING', W/2, H/2+60);

  // 1132
  ctx.font = '50px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('1132', W/2, H/2+150);

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2-100, H/2, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-100, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-120, H/2+40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-80, H/2+40);
  ctx.stroke();

  // animation
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20+10*Math.sin(t), 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
